/// <summary>
/// Extension class for Bank Cheque Table
/// </summary>
[ExtensionOf(tableStr(BankChequeTable))]
public final class METBankChequeTable_Extension
{

}

Method.Source:
    /// <summary>
    /// Payment mode for Presented Cheques and Cancelled Cheques
    /// </summary>
    /// <param name = "_this"></param>
    /// <returns></returns>
    [SysClientCacheDataMethod]
    public static display VendPaymMode paymMode(BankChequeTable _this)
    {
        BankStmtISOReportEntry          bankStmtISOReportEntry;
        VendPaymMode                    vendPaymMode;
        VendTrans                       vendTrans;

        if(_this.ChequeNum)
        {
            //Check if the transaction is reconciled and retrieve Booking Date (Presented Date) of Cheque 
            select EntryReference,BookingDateTime from bankStmtISOReportEntry
                        where ((bankStmtISOReportEntry.EntryReference == _this.ChequeNum)
                        || (bankStmtISOReportEntry.ReferenceNumber == _this.ChequeNum))
                        && bankStmtISOReportEntry.Reconciled == NoYes::Yes
                        && bankStmtISOReportEntry.DataAreaId == '7000';

            if(bankStmtISOReportEntry)
            {
                vendPaymMode = 'CHQ';
            }

            //If the cheque is a cancelled cheque, then run this logic of code
            //Cancelled cheques do not have a reference transaction in the BankStmtISOReportEntry Table
            else if(!bankStmtISOReportEntry)
            {
                select firstonly AccountNum,PaymMode,Closed from vendTrans
                order by ModifiedDateTime desc
                            where vendTrans.AccountNum == _this.RecipientAccountNum
                            //&& vendTrans.TransDate == _this.TransDate
                            && vendTrans.PaymMode == 'No Pay'
                            && vendTrans.PaymReference == _this.ChequeNum;

                //Validate if the method of payment is Cancelled
                if(vendTrans.PaymMode == 'No Pay' && (_this.ChequeStatus == ChequeStatus::Payment))
                {
                    if(vendTrans.LastSettleVoucher == _this.Voucher)
                    {
                        vendPaymMode = vendTrans.PaymMode;
                    }

                    else if(vendTrans.LastSettleVoucher != _this.Voucher)
                    {
                        vendPaymMode = vendTrans.PaymMode;
                    }
                }

                else if(vendTrans.PaymMode != 'No Pay' && (_this.ChequeStatus == ChequeStatus::Payment))
                {
                    vendPaymMode = 'CHQ';
                }
            }         
            
           
        }

        return vendPaymMode;
    }

    [SysClientCacheDataMethod]
    public static display date clearedDt(BankChequeTable _this)
    {
        BankStmtISOReportEntry          bankStmtISOReportEntry;
        date                            chkBookingDate;
        VendPaymMode                    vendPaymMode;
        VendTrans                       vendTrans;

        //Check if the transaction is reconciled and retrieve Booking Date (Presented Date) of Cheque
        if(_this.ChequeNum)
        {
            select EntryReference,BookingDateTime from bankStmtISOReportEntry
                        where ((bankStmtISOReportEntry.EntryReference == _this.ChequeNum)
                        || (bankStmtISOReportEntry.ReferenceNumber == _this.ChequeNum))
                        && bankStmtISOReportEntry.Reconciled == NoYes::Yes
                        && bankStmtISOReportEntry.DataAreaId == '7000';

            if(bankStmtISOReportEntry.EntryReference)
            {
                chkBookingDate = DateTimeUtil::date(bankStmtISOReportEntry.BookingDateTime);
            }

            else if(!bankStmtISOReportEntry.EntryReference)
            {
                select AccountNum,PaymMode,LastSettleDate,Closed,PaymReference from vendTrans
                    order by ModifiedDateTime desc
                            where vendTrans.AccountNum == _this.RecipientAccountNum
                            && vendTrans.PaymReference == _this.ChequeNum
                            //&& vendTrans.TransDate == _this.TransDate
                            && vendTrans.PaymMode == 'No Pay'
                            //&& (vendTrans.LastSettleVoucher == _this.Voucher
                            ;

                if(vendTrans)
                {
                    chkBookingDate = vendTrans.LastSettleDate;
                }
                else if(!vendTrans) 
                {
                    chkBookingDate = DateTimeUtil::date(utcDateTimeNull());
                }

            }

        }


        return chkBookingDate;
    }

/// <summary>
/// Display vendor name
/// </summary>
/// <returns>Returns Vendor Name</returns>
[SysClientCacheDataMethod(true)]
public display VendName displayVendName()
{
    return VendTable::find(this.RecipientAccountNum).name();
}
